import type {Mesh} from '@loaders.gl/core/schema';
import {deduceMeshSchema, getMeshBoundingBox} from '@loaders.gl/core/schema-utils';
import {
  HeightField,
  createMartiniTerrainMesh,
  createDelatinTerrainMesh
} from '@math.gl/geospatial/terrain';
import {addSkirt} from './helpers/skirt';
import {decodeTerrainHeightmapInto} from './decode-terrain-heightmap';
import type {ElevationDecoder} from './terrain-heightmap-types';

export type TerrainOptions = {
  /** Maximum terrain mesh error in meters. */
  meshMaxError: number;
  /** Maximum source-node validation tests per refinement pass; defaults scale with the padded grid. */
  meshMaxSampleTests?: number;
  /** Bounds used to map terrain image coordinates to x/y positions. */
  bounds: number[];
  /** Decoder used to convert terrain image channels to elevation values. */
  elevationDecoder: ElevationDecoder;
  /** Tesselation algorithm used to reconstruct the terrain mesh. */
  tesselator: 'martini' | 'delatin' | 'auto';
  /** Optional skirt height in meters. */
  skirtHeight?: number;
};

type TerrainImage = {
  /** Terrain image pixel data. */
  data: Uint8Array;
  /** Terrain image width in pixels. */
  width: number;
  /** Terrain image height in pixels. */
  height: number;
};

/**
 * Returns generated mesh object from image data
 *
 * @param terrainImage terrain image data
 * @param terrainOptions terrain options
 * @returns mesh object
 */
export function makeTerrainMeshFromImage(
  terrainImage: TerrainImage,
  terrainOptions: TerrainOptions
): Mesh {
  const {bounds, elevationDecoder} = terrainOptions;

  const {data, width, height} = terrainImage;

  let terrain;
  let mesh;
  switch (terrainOptions.tesselator) {
    case 'martini':
      terrain = getTerrain(data, width, height, elevationDecoder, terrainOptions.tesselator);
      mesh = getTerrainTileMesh(terrainOptions, width, height, terrain, 'martini');
      break;
    case 'delatin':
      terrain = getTerrain(data, width, height, elevationDecoder, terrainOptions.tesselator);
      mesh = getTerrainTileMesh(terrainOptions, width, height, terrain, 'delatin');
      break;
    // auto
    default:
      if (width === height && !(height & (width - 1))) {
        terrain = getTerrain(data, width, height, elevationDecoder, 'martini');
        mesh = getTerrainTileMesh(terrainOptions, width, height, terrain, 'martini');
      } else {
        terrain = getTerrain(data, width, height, elevationDecoder, 'delatin');
        mesh = getTerrainTileMesh(terrainOptions, width, height, terrain, 'delatin');
      }
      break;
  }

  const {vertices} = mesh;
  let {triangles} = mesh;
  let attributes = getMeshAttributes(vertices, terrain, width, height, bounds);

  // Compute bounding box before adding skirt so that z values are not skewed
  const boundingBox = getMeshBoundingBox(attributes);

  if (terrainOptions.skirtHeight) {
    const {attributes: newAttributes, triangles: newTriangles} = addSkirt(
      attributes,
      triangles,
      terrainOptions.skirtHeight
    );
    attributes = newAttributes;
    triangles = newTriangles;
  }

  const topology = 'triangle-list';
  const mode = 4; // TRIANGLES
  const schema = deduceMeshSchema(attributes, {
    topology,
    mode: String(mode),
    boundingBox: JSON.stringify(boundingBox)
  });

  return {
    // Data return by this loader implementation
    loaderData: {
      header: {}
    },
    header: {
      vertexCount: triangles.length,
      boundingBox: boundingBox ?? undefined
    },
    schema,
    topology,
    mode,
    indices: {value: Uint32Array.from(triangles), size: 1},
    attributes
  };
}

/** Adapts the padded, north-first image grid to upstream adaptive terrain meshing. */
function getTerrainTileMesh(
  terrainOptions: TerrainOptions,
  width: number,
  height: number,
  terrain: Float32Array,
  tesselator: 'martini' | 'delatin'
) {
  const field = new HeightField({
    width: width + 1,
    height: height + 1,
    heights: terrain,
    rowStep: [0, -1]
  });
  // Fully refined RTIN triangles can inspect 32 neighboring grid nodes per source cell.
  const options = {
    maxError: terrainOptions.meshMaxError,
    maxSampleTests: terrainOptions.meshMaxSampleTests ?? Math.max(10_000_000, 32 * terrain.length)
  };
  const mesh =
    tesselator === 'martini'
      ? createMartiniTerrainMesh(field, options)
      : createDelatinTerrainMesh(field, options);
  return {vertices: mesh.gridCoordinates, triangles: mesh.indices};
}

function getTerrain(
  imageData: Uint8Array,
  width: number,
  height: number,
  elevationDecoder: ElevationDecoder,
  tesselator: 'martini' | 'delatin'
) {
  // From Martini demo
  // https://observablehq.com/@mourner/martin-real-time-rtin-terrain-mesh
  const terrain = new Float32Array((width + 1) * (height + 1));
  decodeTerrainHeightmapInto(
    {data: imageData, width, height},
    elevationDecoder,
    terrain,
    width + 1
  );

  if (tesselator === 'martini') {
    // backfill bottom border
    for (let i = (width + 1) * width, x = 0; x < width; x++, i++) {
      terrain[i] = terrain[i - width - 1];
    }
    // backfill right border
    for (let i = height, y = 0; y < height + 1; y++, i += height + 1) {
      terrain[i] = terrain[i - 1];
    }
  }

  return terrain;
}

function getMeshAttributes(
  vertices,
  terrain: Uint8Array,
  width: number,
  height: number,
  bounds: number[]
) {
  const gridSize = width + 1;
  const numOfVerticies = vertices.length / 2;
  // vec3. x, y in pixels, z in meters
  const positions = new Float32Array(numOfVerticies * 3);
  // vec2. 1 to 1 relationship with position. represents the uv on the texture image. 0,0 to 1,1.
  const texCoords = new Float32Array(numOfVerticies * 2);

  const [minX, minY, maxX, maxY] = bounds || [0, 0, width, height];
  const xScale = (maxX - minX) / width;
  const yScale = (maxY - minY) / height;

  for (let i = 0; i < numOfVerticies; i++) {
    const x = vertices[i * 2];
    const y = vertices[i * 2 + 1];
    const pixelIdx = y * gridSize + x;

    positions[3 * i + 0] = x * xScale + minX;
    positions[3 * i + 1] = -y * yScale + maxY;
    positions[3 * i + 2] = terrain[pixelIdx];

    texCoords[2 * i + 0] = x / width;
    texCoords[2 * i + 1] = y / height;
  }

  return {
    POSITION: {value: positions, size: 3},
    TEXCOORD_0: {value: texCoords, size: 2}
    // NORMAL: {}, - optional, but creates the high poly look with lighting
  };
}
